/** Runtime shape of public/data/specials.json, generated by
 *  scripts/extract_specials.py from sources/special-notices.tsv.
 *
 *  Rows are a faithful transcription of the hand-maintained condition table:
 *  no artist names, no progress state. Who a row belongs to is decided by
 *  `scope` + the assignment the user makes in the UI. */
export type SpecialKind = 'condition' | 'note';
export type SpecialPhase = 'prepare' | 'trigger' | 'notice' | '-';
export type SpecialType =
  | 'stat' | 'count' | 'item' | 'cert' | 'course' | 'resource' | 'flag' | '-';
export type SpecialScope = 'global' | 'artist' | 'group' | 'role' | 'notice' | '-';

/** A hash link already resolved against guide.json's event blocks. */
export interface SpecialLink {
  kind: 'guide' | 'tracker';
  href: string;
  node: string;
  /** The guide's event number, e.g. "14". Only present on event deep links. */
  event?: string;
}

export interface SpecialRow {
  id: string;
  notice: string;
  /** "-" for company-wide rows; "main", "group" or "role:<位名>" otherwise. */
  slot: string;
  phase: SpecialPhase;
  kind: SpecialKind;
  type: SpecialType;
  scope: SpecialScope;
  name: string;
  /** Raw target as written in the table: "630~700", "4000万", "300/300/3", "10". */
  target: string;
  hint: string;
  source: string;
  link: SpecialLink | null;
}

export interface SpecialNotice {
  id: string;
  title: string;
  /** null for the top-of-page global prerequisite. */
  guideNode: string | null;
  conditionCount: number;
  noteCount: number;
  slots: string[];
  /** 落入凡间的天使 / 万年之恋 go to exactly one artist: the main slot holds
   *  one name and cannot grow into a candidate pool. */
  soloMain: boolean;
}

export interface SpecialsData {
  version: number;
  meta: {
    generatedBy: string;
    source: string;
  };
  stats: {
    rows: number;
    conditions: number;
    notes: number;
    scopeCounts: Record<string, number>;
    eventAnchorsChecked: number;
  };
  notices: SpecialNotice[];
  rows: SpecialRow[];
}
